insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NZ:accountant','2026-08-11',null,48.56,101000,0,0,0,0,10,10,0,5,5,30,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 221111 Accountant (General).','shortage_note','Accountant 221111 is not on the current 9 March 2026 Green List; no shortage credit is assigned.','visa_basis','Standard skilled-work/SMC treatment for a skill-level-1 occupation when current job, pay and applicant requirements are met; 5/10. The announced 24 August 2026 SMC occupational-registration rule for accountants who can undertake Qualified Statutory Accountant work and are CPA Australia members is future policy and is not pre-scored on 11 August 2026.','salary_method','Midpoint of Tahatū current most-common Accountant and Auditor annual pay range NZD 71,000-131,000; 10/10.','entry_basis','Relevant tertiary accounting/business study is normally needed; CA/CPA pathways may be valuable but are not universal for every generic accountant role; 10/15.','entry_burden_basis','Generic accountant work does not require one universal statutory practising licence; regulated services can impose additional requirements; 5/5.'),'2026-08-11'),
('NZ:financial-analyst','2026-08-11',null,46.88,97500,0,0,0,0,10,8,0,5,5,28,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 221111 Accountant (General), Financial Analyst specialisation, used for corporate finance/budget-analysis scope rather than client financial-advice work.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Standard skilled-work/SMC treatment for the exact skill-level-1 classification when role and pay requirements are met; 5/10.','salary_method','Midpoint of Tahatū current most-common Finance Analyst annual pay range NZD 73,000-122,000; 8/10.','entry_basis','Finance, economics, accounting, law or similar bachelor-level study is a common route and relevant experience may be needed; 10/15.','entry_burden_basis','The canonical corporate finance analyst is not treated as a regulated financial adviser; no universal statutory registration is required; 5/5.'),'2026-08-11'),
('NZ:business-analyst','2026-08-11',null,46.88,97500,0,0,0,0,8,8,0,5,5,26,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 224711 Management Consultant, whose Version 1.3 specialisations include Business Analyst; non-ICT business-analysis scope only.','shortage_note','No Green List status or recurring occupation-specific shortage credit is used. ICT Business Analyst 261111 benefits are not borrowed for this non-ICT canonical profile.','visa_basis','Standard skilled-work/SMC treatment for a skill-level-1 occupation when duties match 224711 and current requirements are met; 5/10.','salary_method','Midpoint of Tahatū current most-common Business Analyst annual pay range NZD 85,000-110,000; 8/10.','entry_basis','Tahatū indicates a relevant tertiary qualification is needed, typically business, management, computer science, economics or similar; 8/15.','entry_burden_basis','No statutory professional registration is required; optional industry certification may help; 5/5.'),'2026-08-11'),
('NZ:supply-chain-analyst','2026-08-11',null,36.78,76500,0,0,0,0,12,6,0,3,5,26,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Canonical Supply Chain Analyst is not forced into ANZSCO 224714 because that occupation was introduced in an Australian-only later ANZSCO update and is not part of ANZSCO 1.3. A specific NZ role must be classified by its actual duties.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Duty-based classification is required for a specific AEWV/SMC case; classification ambiguity is scored conservatively at 3/10.','salary_method','Midpoint of Tahatū current most-common Logistics Specialist annual pay range NZD 62,000-91,000, used as the closest transparent supply-chain operations proxy; 6/10.','entry_basis','Tahatū logistics pathways include advanced certificate/diploma or relevant business/management tertiary study plus experience; 12/15.','entry_burden_basis','No statutory occupational registration is required; 5/5.'),'2026-08-11'),
('NZ:human-resources-specialist','2026-08-11',null,44.47,92500,0,0,0,0,12,8,0,5,5,30,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 223111 Human Resource Adviser, aligned to the canonical HR specialist/adviser scope.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Standard skilled-work/SMC treatment for a skill-level-1 occupation when current role and pay requirements are met; 5/10.','salary_method','Midpoint of Tahatū current most-common Human Resources Specialist annual pay range NZD 69,000-116,000; 8/10.','entry_basis','Relevant business/HR tertiary study can help and Tahatū describes 0-3 years of training with experience valued; 12/15.','entry_burden_basis','No statutory occupational registration is required; 5/5.'),'2026-08-11'),
('NZ:marketing-specialist','2026-08-11',null,48.32,100500,0,0,0,0,15,10,0,5,5,35,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 225113 Marketing Specialist is an exact canonical match.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Standard skilled-work/SMC treatment for a skill-level-1 occupation when current requirements are met; 5/10.','salary_method','Midpoint of Tahatū current most-common Marketing Specialist annual pay range NZD 66,000-135,000; 10/10.','entry_basis','Tahatū describes experience as important and diploma-level business/digital-marketing study as useful, providing a relatively accessible professional entry path; 15/15.','entry_burden_basis','No statutory occupational registration is required; 5/5.'),'2026-08-11'),
('NZ:auditor','2026-08-11',null,48.56,101000,20,0,0,0,10,10,0,10,4,54,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Explicit roll-up of ANZSCO 221213 External Auditor and 221214 Internal Auditor.','shortage_note','Both External Auditor 221213 and Internal Auditor 221214 are on the current Green List Tier 1 with remuneration of at least NZD 45.50/hour; direct current policy-demand signal 20/20.','visa_basis','Green List Tier 1 can support Straight to Residence when the role meets the current NZD 45.50/hour remuneration condition and other requirements; Tahatū midpoint is above that threshold; 10/10.','salary_method','Midpoint of Tahatū current most-common Accountant and Auditor annual pay range NZD 71,000-131,000; 10/10.','entry_basis','Relevant accounting/business study and professional accounting/audit development are common; 10/15.','entry_burden_basis','The generic roll-up is not universally licensed because internal audit is included, but auditors performing FMC audits must hold an auditor licence and affected firms must be registered; 4/5.'),'2026-08-11'),
('NZ:project-manager','2026-08-11',null,51.20,106500,0,0,0,0,12,10,0,3,5,30,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Project Manager is a cross-industry canonical title spanning construction, ICT, engineering and other sectors, so no single ANZSCO 1.3 code is promoted to the generic profile.','shortage_note','No Green List credit is borrowed from Construction Project Manager 133111 or ICT Project Manager 135112; shortage 0/20 for the generic role.','visa_basis','A specific project-management job must be classified by its actual industry and duties; conservative 3/10 until that classification is known.','salary_method','Midpoint of Tahatū current most-common Project Manager annual pay range NZD 74,000-139,000; 10/10.','entry_basis','Tahatū describes experience as normally needed, with relevant tertiary study and PMI/PRINCE2/PMBOK/Agile credentials useful rather than universally mandatory; 12/15.','entry_burden_basis','No universal statutory project-management licence or register; 5/5.'),'2026-08-11')
